#!/bin/bash
# CHEAT (for testing the tests only). Ports nothing: writes a tiny Go program
# that ignores its input and prints the lines of the VISIBLE tests/data/expected.txt.
# Grading uses the hidden set, so this must score below 0.2.
set -euo pipefail
cd /workspace/repo

cat > go.mod <<'EOF_GOMOD'
module github.com/cheat/answers

go 1.23
EOF_GOMOD

base64 -d > answers.txt <<'EOF_B64'

EOF_B64

cat > main.go <<'EOF_GO'
package main

import (
	_ "embed"
	"os"
)

//go:embed answers.txt
var answers []byte

func main() { os.Stdout.Write(answers) }
EOF_GO

go build ./...
